<?php
namespace App\Http\Controllers;
use App\Models\DeliveryZone; use App\Models\Order; use App\Models\OrderItem; use App\Models\Product; use App\Models\ProductVariant; use App\Services\BkashService; use App\Services\CartService; use App\Services\OrderService; use App\Services\SmsService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Throwable;
class CheckoutController extends Controller { public function __construct(private CartService $cart,private OrderService $orders,private BkashService $bkash,private SmsService $sms){}
public function show(){if(!$this->cart->count())return redirect()->route('cart.index')->with('error','Your cart is empty.');return view('checkout',['items'=>$this->cart->items(),'subtotal'=>$this->cart->subtotal(),'customer'=>auth()->user(),'deliveryZones'=>DeliveryZone::where('is_active',true)->orderBy('district')->get()]);}
public function place(Request $r){$data=$r->validate(['customer_name'=>'required|string|max:120','phone'=>['required','regex:/^(?:\+?88)?01[3-9]\d{8}$/'],'email'=>'nullable|email|max:190','district'=>'required|string|max:120','area'=>'required|string|max:120','address'=>'required|string|max:500','note'=>'nullable|string|max:1000','payment_method'=>'required|in:cod,bkash']);$cart=$this->cart->items();abort_if(!$cart,422,'Cart is empty.');if($data['payment_method']==='bkash'&&!$this->bkash->enabled())return back()->withInput()->with('error','bKash is not enabled yet.');
foreach($cart as $item){$p=Product::find($item['product_id']);$v=$item['variant_id']?ProductVariant::find($item['variant_id']):null;$stock=$v?->stock??$p?->stock??0;if(!$p||!$p->is_active||$stock<$item['quantity'])return back()->withInput()->with('error',"{$item['name']} has insufficient stock.");}
$subtotal=$this->cart->subtotal();$zone=DeliveryZone::where('is_active',true)->whereRaw('LOWER(district)=?',[strtolower(trim($data['district']))])->first();$delivery=$zone?(float)$zone->charge:(strtolower(trim($data['district']))==='dhaka'?config('store.dhaka_delivery'):config('store.outside_delivery'));
$order=DB::transaction(function()use($data,$cart,$subtotal,$delivery){$o=Order::create([...$data,'user_id'=>auth()->id(),'order_number'=>'AS'.now()->format('ymd').strtoupper(Str::random(6)),'subtotal'=>$subtotal,'delivery_charge'=>$delivery,'total'=>$subtotal+$delivery,'payment_status'=>'unpaid','status'=>'pending','stock_committed'=>false]);foreach($cart as $i)OrderItem::create(['order_id'=>$o->id,'product_id'=>$i['product_id'],'product_variant_id'=>$i['variant_id'],'product_name'=>$i['name'],'sku'=>$i['sku'],'variant_name'=>$i['variant_name'],'price'=>$i['price'],'quantity'=>$i['quantity'],'line_total'=>$i['price']*$i['quantity']]);return $o;});
if($data['payment_method']==='cod'){try{$this->orders->commitStock($order);}catch(Throwable $e){$order->delete();return back()->withInput()->with('error',$e->getMessage());}$this->cart->clear();$this->sms->send($order->phone,"Aesthetic Store order {$order->order_number} received. Total Tk {$order->total}.");return redirect()->route('order.success',$order->order_number);} try{$payment=$this->bkash->createPayment($order);session(['pending_order'=>$order->order_number]);return redirect()->away($payment['bkashURL']);}catch(Throwable $e){$order->update(['payment_status'=>'failed']);return back()->with('error',$e->getMessage());}}
public function success(string $orderNumber){$order=Order::with('items')->where('order_number',$orderNumber)->firstOrFail();return view('order-success',compact('order'));} public function trackForm(){return view('track');} public function track(Request $r){$d=$r->validate(['order_number'=>'required|string','phone'=>'required|string']);$order=Order::with(['items','shipmentEvents'])->where('order_number',$d['order_number'])->where('phone',$d['phone'])->first();return view('track',['searched'=>true,'order'=>$order]);}}
